#include <map>
#include <string>
#include <iostream>

int main() {
    std::multimap<int, std::string> mmap = {{1, "A"}, {1, "B"}, {2, "C"}};

    // 1. Remove ALL elements with key 1
    size_t count_removed = mmap.erase(1);
    std::cout << "Removed " << count_removed << " elements.\n"; // Output: 2

    // 2. Targeted removal (if duplicates exist)
    mmap.insert({3, "X"});
    mmap.insert({3, "Y"});

    auto pos = mmap.find(3); // Finds the first element with key 3
    if (pos != mmap.end()) {
        mmap.erase(pos); // Only removes {3, "X"}
    }

    // Key 3 still exists (the element {3, "Y"})
}
